static unsigned char *in = NULL, *out = NULL;
static size_t inlen = 0, outlen = 0;
static struct sc_context *ctx = NULL;

int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
{
    if (!ctx)
        sc_establish_context(&ctx, "fuzz");

    if (outlen < Size*2) {
        unsigned char *p = realloc(out, Size*2);
        if (p) {
            out = p;
            outlen = Size*2;
        }
    }

    if (inlen < Size) {
        unsigned char *p = realloc(in, Size);
        if (p) {
            in = p;
        }
    }
    memcpy(in, Data, Size);

    sc_asn1_sig_value_sequence_to_rs(ctx,
            Data, Size,
            out, outlen);

    unsigned char *p = NULL;
    size_t plen = 0;
    sc_asn1_sig_value_rs_to_sequence(ctx,
            in, Size,
            &p, &plen);
    free(p);

    return 0;
}

void sc_asn1_print_tags(const u8 * buf, size_t buflen)
{
        print_tags_recursive(buf, buf, buflen, 0);
}

const u8 *sc_asn1_find_tag(sc_context_t *ctx, const u8 * buf,
        size_t buflen, unsigned int tag_in, size_t *taglen_in)
{
        size_t left = buflen, taglen;
        const u8 *p = buf;

        *taglen_in = 0;
        while (left >= 2) {
                unsigned int cla = 0, tag, mask = 0xff00;

                buf = p;
                /* read a tag */
                if (sc_asn1_read_tag(&p, left, &cla, &tag, &taglen) != SC_SUCCESS
                                || p == NULL)
                        return NULL;

                left -= (p - buf);
                /* we need to shift the class byte to the leftmost
                 * byte of the tag */
                while ((tag & mask) != 0) {
                        cla  <<= 8;
                        mask <<= 8;
                }
                /* compare the read tag with the given tag */
                if ((tag | cla) == tag_in) {
                        /* we have a match => return length and value part */
                        if (taglen > left)
                                return NULL;
                        *taglen_in = taglen;
                        return p;
                }
                /* otherwise continue reading tags */
                left -= taglen;
                p += taglen;
        }
        return NULL;
}

